{"code": "import pandas as pd, numpy as np
import statsmodels.formula.api as smf
df = pd.read_csv('data/explore.csv')
for e in ['soil_ph','biochar_g']:
    print("===",e)
    for f in df['farm'].unique():
        d = df[df['farm']==f].dropna(subset=[e,'yield_kg'])
        m = smf.ols(f'yield_kg ~ {e}', data=d).fit()
        print(f"  {f:6s} coef={m.params[e]:7.3f} p={m.pvalues[e]:.3f} n={len(d)}")
"}
